import pytest

CASES = [
    {"q": "refund order A-1", "expect_tool": "issue_refund"},
    {"q": "where is order A-2", "expect_tool": "track_order"},
]

@pytest.mark.parametrize("case", CASES, ids=lambda c: c["q"])
def test_agent_picks_right_tool(case, agent):
    trace = agent.run(case["q"])
    # assertion = a scorer over one labeled case
    assert trace.first_tool == case["expect_tool"]

def gate(score: float, baseline: float, tol: float = 0.02) -> None:
    # pass if within tolerance of (or above) the baseline
    if score < baseline - tol:
        raise SystemExit(
            f"quality regression: {score:.3f} < {baseline:.3f} - {tol}"
        )
    print(f"passed gate: {score:.3f} (baseline {baseline:.3f})")

gate(score=0.895, baseline=0.91)   # within 2pt tolerance -> passes

