from statistics import mean

def run_suite(cases, agent, score_fn, baseline, tol=0.02, samples=3):
    per_case = []
    for case in cases:
        # average several samples so one noisy run doesn't dominate
        runs = [score_fn(agent(case["input"]), case["gold"])
                for _ in range(samples)]
        per_case.append(mean(runs))
    score = mean(per_case)                 # suite score
    return {"score": score, "passed": score >= baseline - tol}

if __name__ == "__main__":
    def agent(x):
        return {"a": "tool_a", "b": "tool_b"}[x]
    def score_fn(out, gold):
        return 1.0 if out == gold else 0.0
    cases = [{"input": "a", "gold": "tool_a"},
             {"input": "b", "gold": "tool_b"}]
    print(run_suite(cases, agent, score_fn, baseline=0.91))
